$p='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\constant\item.ks'
$pairs=@(
@('自身のファミリアに『受けるダメージを3回まで0にする』状態を付与する。神上園世界が発動した場合のみ『受けるダメージを999回まで0にする』に変化する。','使我方使魔获得“受到的伤害最多 3 次变为 0”的状态。仅在神上园世界发动时，变为最多 999 次。'),@('SPDが遅いファミリアから先に行動する領域を永続で展開する。この領域は上書きされない。','永久展开由 SPD 较低的使魔优先行动的领域。该领域无法被覆盖。'),@('スタンバイフェイズ前にも発動可能。互いのサポートを消滅させる。その後、消滅させた数だけデッキのアルカナを手札に加える。','准备阶段前也能发动。使双方支援使魔消失，随后从牌组加入等量阿尔卡那到手牌。'),@('ATK・DEF・SPDのうち、ランダムで2つのステータスLv+2。残り1つのステータスLv-2。','随机使 ATK、DEF、SPD 中两项属性等级 +2，剩余一项等级 -2。'),@('召喚フェイズを終了し、直前に使用されたサポートをファミリアとして召喚する。事前にサポートを選択していた場合、そのサポートも設置する。','结束召唤阶段，并将最近使用的支援使魔作为使魔召唤。若事先选择了支援使魔，也会将其放置。'),@('領域展開時、自身のファミリアのSPDが2倍になる。そうでない時、自身のファミリアのSPDが0.5倍になる。','领域展开时，我方使魔的 SPD 变为 2 倍；否则变为 0.5 倍。'),@('互いのファミリアの与えるダメージが1.2倍になる。','双方使魔造成的伤害变为 1.2 倍。'),@('バトル開始時の手札が7枚になる。自身のファミリアが撃破された時、アルカナを手札に加えられない。（『宝札』は1種類しか所有出来ない）','战斗开始时手牌变为 7 张。我方使魔被击破时，无法将阿尔卡那加入手牌。（『宝札』只能持有一种）'),@('バトル開始時の手札が4枚になる。自身のファミリアが撃破された時、追加でアルカナを1枚手札に加える。（『宝札』は1種類しか所有出来ない）','战斗开始时手牌变为 4 张。我方使魔被击破时，额外将 1 张阿尔卡那加入手牌。（『宝札』只能持有一种）'),@('使用したサポートは消滅せず、手札に戻る。自身のファミリアが撃破された時、アルカナを手札に加えられない。（『宝札』は1種類しか所有出来ない）','使用过的支援使魔不会消失，而会回到手牌。我方使魔被击破时，无法将阿尔卡那加入手牌。（『宝札』只能持有一种）'),@('互いに展開する領域の持続ターンが8ターンになる。','双方展开的领域持续 8 回合。'),@('自身のファミリアのSPDが相手のファミリアのSPDの半分以下の場合、与えるダメージが1.2倍になる。SPDが2倍以上の場合、与えるダメージが0.8倍になる。','我方使魔的 SPD 不高于对方的一半时，造成的伤害变为 1.2 倍；达到对方 2 倍以上时，造成的伤害变为 0.8 倍。'),@('自身のファミリアのHPが最大値以上の時、受けるダメージを半分にする。','我方使魔 HP 达到最大值以上时，受到的伤害减半。'),@('ターン終了時、自身のファミリアのHPを10回復する。','每回合结束时，我方使魔恢复 10 点 HP。'),@('相手のファミリアの攻撃時、10%の確率で受けるダメージを0にする。','对方使魔攻击时，有 10% 概率使受到的伤害变为 0。'),@('相手のファミリアを撃破した時、自身のファミリアのATKLv+1。','击破对方使魔时，我方使魔 ATK 等级 +1。'),@('相手にサポートが存在する時、与えるダメージが1.2倍になる。','对方存在支援使魔时，造成的伤害变为 1.2 倍。'),@('アクションフェイズ開始時、自身にサポートが存在しないならATK・DEF・SPDのうちランダムで一つのステータスLv+1。','行动阶段开始时，若我方没有支援使魔，则随机使 ATK、DEF、SPD 中一项属性等级 +1。'),@('自身のファミリアの召喚時、ATK・DEF・SPDのうちランダムで一つのステータスLv-1。','我方使魔召唤时，随机使 ATK、DEF、SPD 中一项属性等级 -1。'),@('戦闘勝利時に獲得出来る魔力の欠片が2倍になる。','战斗胜利时获得的魔力碎片变为 2 倍。'),@('攻高守低の咒物','攻高守低之咒物'),@('攻高敏低の咒物','攻高敏低之咒物'),@('守高攻低の咒物','守高攻低之咒物'),@('守高敏低の咒物','守高敏低之咒物'),@('敏高攻低の咒物','敏高攻低之咒物')
)
